-- رسايل الحجز الجديدة (نص العميل + نص مقدم الخدمة). الشركات اللي لسه على
-- النص الافتراضي القديم بس هي اللي بتتحدّث (اللي التاجر كتبه بنفسه مابيتلمسش)
ALTER TABLE "booking_settings" ALTER COLUMN "waTemplate" SET DEFAULT E'🔔 Booking Request Received!\n\nHi {customer_name},\nThank you for booking with us! Your request has been sent to {provider_name}.\n\n📋 Booking Details:\n• Service: {service_type}\n• Date: {date}\n• Time: {time}\n• Provider: {provider_name}\n\n📞 Need assistance? Contact the provider directly at: {provider_phone}\n\nWe look forward to serving you! ✨';
ALTER TABLE "booking_settings" ALTER COLUMN "waMerchantTemplate" SET DEFAULT E'🔔 New Booking Notification\n\nHi {provider_name},\nYou have received a new booking through the platform. Here are the details:\n\n👤 Customer Name: {customer_name}\n\n📞 Contact Number: {phone}\n\n🛠️ Requested Service: {service_type}\n\n📅 Date: {date}\n\n⏰ Time: {time}\n\n📌 Please review your dashboard to manage or confirm this request';

UPDATE "booking_settings" SET "waTemplate" = E'🔔 Booking Request Received!\n\nHi {customer_name},\nThank you for booking with us! Your request has been sent to {provider_name}.\n\n📋 Booking Details:\n• Service: {service_type}\n• Date: {date}\n• Time: {time}\n• Provider: {provider_name}\n\n📞 Need assistance? Contact the provider directly at: {provider_phone}\n\nWe look forward to serving you! ✨'
WHERE "waTemplate" IN (E'Hello {name} 👋\nYour booking at {business} is confirmed ✅\n\n🔹 Service: {services}\n📅 Date: {date}\n⏰ Time: {time}\n👤 With: {resource}\n💳 Payment: {payment}\n🔖 Booking ref: {reference}\n\nNeed to reschedule or cancel? Just reply to this message. We look forward to seeing you!', E'Hi! Your slot is confirmed for today. Show this ticket at check-in — no payment needed in advance.');
UPDATE "booking_settings" SET "waMerchantTemplate" = E'🔔 New Booking Notification\n\nHi {provider_name},\nYou have received a new booking through the platform. Here are the details:\n\n👤 Customer Name: {customer_name}\n\n📞 Contact Number: {phone}\n\n🛠️ Requested Service: {service_type}\n\n📅 Date: {date}\n\n⏰ Time: {time}\n\n📌 Please review your dashboard to manage or confirm this request'
WHERE "waMerchantTemplate" IN (E'🔔 New booking — {business}\n\n👤 {name} · {phone}\n🔹 {services}\n🧑‍💼 With: {resource}\n📅 {date} at {time}\n💳 {payment}\n🔖 Ref: {reference}', E'🔔 New booking\n{name} · {phone}\n{resource}\n{date} at {time}');
